rojectColor\"\n                    v-model=\"form.color\"\n                    type=\"color\"\n                    class=\"color-input\">\n                <NcButton v-if=\"form.color\"\n                    type=\"tertiary\"\n                    @click=\"form.color = null\">\n                    {{ t('worktime', 'Zurücksetzen') }}\n                </NcButton>\n            </div>\n        </div>\n\n        <div class=\"form-group\">\n            <NcCheckboxRadioSwitch :checked.sync=\"form.isActive\">\n                {{ t('worktime', 'Aktiv') }}\n            </NcCheckboxRadioSwitch>\n        </div>\n\n        <div class=\"form-actions\">\n            <NcButton type=\"tertiary\" @click=\"cancel\">\n                {{ t('worktime', 'Abbrechen') }}\n            </NcButton>\n            <NcButton type=\"primary\" :disabled=\"!isValid\" @click=\"save\">\n                {{ t('worktime', 'Speichern') }}\n            </NcButton>\n        </div>\n    </div>\n</template>\n\n<script>\nimport NcButton from '@nextcloud/vue/dist/Components/NcButton.js'\nimport NcCheckboxRadioSwitch from '@nextcloud/vue/dist/Components/NcCheckboxRadioSwitch.js'\nimport { mapActions } from 'vuex'\nimport { showSuccessMessage, showErrorMessage } from '../utils/errorHandler.js'\n\nexport default {\n    name: 'ProjectForm',\n    components: {\n        NcButton,\n        NcCheckboxRadioSwitch,\n    },\n    props: {\n        project: {\n            type: Object,\n            default: null,\n        },\n    },\n    data() {\n        return {\n            form: {\n                name: '',\n                code: null,\n                description: null,\n                color: null,\n                isActive: true,\n                isBillable: true,\n            },\n        }\n    },\n    computed: {\n        isEdit() {\n            return !!this.project\n        },\n        isValid() {\n            return this.form.name.trim().length > 0\n        },\n    },\n    watch: {\n        project: {\n            immediate: true,\n            handler(project) {\n                if (project) {\n                    this.form = {\n                        name: project.name || '',\n                        code: project.code || null,\n                        description: project.description || null,\n                        color: project.color || null,\n                        isActive: project.isActive ?? true,\n                        isBillable: project.isBillable ?? true,\n                    }\n                } else {\n                    this.resetForm()\n                }\n            },\n        },\n    },\n    methods: {\n        ...mapActions('projects', ['createProject', 'updateProject']),\n        resetForm() {\n            this.form = {\n                name: '',\n                code: null,\n                description: null,\n                color: null,\n                isActive: true,\n                isBillable: true,\n            }\n        },\n        cancel() {\n            this.$emit('cancel')\n        },\n        async save() {\n            try {\n                const data = {\n                    name: this.form.name.trim(),\n                    code: this.form.code?.trim() || null,\n                    description: this.form.description?.trim() || null,\n                    color: this.form.color || null,\n                    isActive: this.form.isActive,\n                    isBillable: this.form.isBillable,\n                }\n\n                if (this.isEdit) {\n                    await this.updateProject({ id: this.project.id, data })\n                    showSuccessMessage(this.t('worktime', 'Projekt aktualisiert'))\n                } else {\n                    await this.createProject(data)\n                    showSuccessMessage(this.t('worktime', 'Projekt erstellt'))\n                }\n\n                this.$emit('saved')\n            } catch (error) {\n                showErrorMessage(error.message || this.t('worktime', 'Fehler beim Speichern'))\n            }\n        },\n    },\n}\n</script>\n\n<style scoped>\n.project-form {\n    padding: 20px;\n}\n\n.project-form h3 {\n    margin-top: 0;\n    margin-bottom: 16px;\n}\n\n.form-group {\n    margin-bottom: 16px;\n}\n\n.form-group label {\n    display: block;\n    margin-bottom: 4px;\n    font-weight: 500;\n}\n\n.form-row {\n    display: flex;\n    gap: 16px;\n    align-items: flex-start;\n}\n\n.form-row .form-group {\n    flex: 1;\n}\n\n.input-field {\n    width: 100%;\n    padding: 8px;\n    border: 1px solid var(--color-border);\n    border-radius: var(--border-radius);\n    background: var(--color-main-background);\n    color: var(--color-main-text);\n}\n\n.textarea-field {\n    resize: vertical;\n    font-family: inherit;\n}\n\n.color-picker-row {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n\n.color-input {\n    width: 48px;\n    height: 36px;\n    padding: 2px;\n    border: 1px solid var(--color-border);\n    border-radius: var(--border-radius);\n    cursor: pointer;\n}\n\n.form-actions {\n    display: flex;\n    justify-content: flex-end;\n    gap: 8px;\n    margin-top: 16px;\n}\n</style>\n"],"sourceRoot":""}]);
